    puts "Loading constraints from [lindex $sdc_files 0]..."
    source [lindex $sdc_files 0]
} else {
    puts "No SDC files found in current directory, checking designs directory..."
    set sdc_files [glob -nocomplain "designs/sky130hd/ibex/*.sdc"]
    puts "Found SDC files: $sdc_files"
    if {[llength $sdc_files] > 0} {
        source [lindex $sdc_files 0]
    }
}

