set sites [get_site_defs *]
puts "Available sites: $sites"
# Use the first available site
if {[llength $sites] > 0} {
    set site [lindex $sites 0]
    puts "Using site: $site"
} else {
    puts "ERROR: No sites found in LEF"
}

puts "Getting routing layers..."
